@lru_cache(maxsize=22)
def _decode(key):
    item=PACKED.get(key)
    if item is None:
        return None
    xlo,ylo,nx,ny,encoded,digest=item
    data=zlib.decompress(base64.b85decode(encoded))
    if len(data)!=nx*ny or hashlib.sha256(data).hexdigest()!=digest:
        raise ValueError('Static navigation cache checksum mismatch')
    return xlo,ylo,nx,ny,data


def get_graph(identity,cell,shape):
    if tuple(identity)!=IDENTITY or shape is None:
        return None
    rounded=tuple(round(float(value),3) for value in shape)
    if any(abs(float(value)-rounded[i])>1e-9 for i,value in enumerate(shape)):
        return None
    return _decode((float(cell),*rounded))
